export { migrateSession } from './migrator.mjs';
export { readSession } from './reader.mjs';
export { writeSession } from './writer.mjs';
export { summarizeSessions } from './summary.mjs';

function invalid(message) {
  throw new Error(`Invalid session record: ${message}`);
}

export function migrateSession(record) {
  if (!record || typeof record !== 'object') invalid('expected an object');
  if (record.version === 2) return record;
  if (record.version !== 1) invalid('unsupported version');
  if (!record.id || !record.user || !record.startedAt || !Array.isArray(record.turns)) {
    invalid('missing required v1 fields');
  }

  // BUG: this mutates the caller and discards metadata while translating the schema.
  record.version = 2;
  record.owner = { id: record.user };
  record.createdAt = record.startedAt;
  record.messages = record.turns.map(turn => ({ role: turn.role, content: turn.text }));
  record.metadata = {};
  delete record.user;
  delete record.startedAt;
  delete record.turns;
  return record;
}

import { readFile } from 'node:fs/promises';
import { migrateSession } from './migrator.mjs';

export async function readSession(file) {
  let record;
  try {
    record = JSON.parse(await readFile(file, 'utf8'));
  } catch (error) {
    throw new Error(`Invalid session record: ${error.message}`);
  }
  return migrateSession(record);
}

import { migrateSession } from './migrator.mjs';

export function summarizeSessions(records) {
  // BUG: sorting the caller's array violates the public purity contract.
  return records.sort((a, b) => a.startedAt.localeCompare(b.startedAt)).map(record => {
    const session = migrateSession(record);
    return {
      id: session.id,
      ownerId: session.owner.id,
      createdAt: session.createdAt,
      messageCount: session.messages.length,
    };
  });
}

import { writeFile } from 'node:fs/promises';
import { migrateSession } from './migrator.mjs';

export async function writeSession(file, record) {
  const migrated = migrateSession(record);
  await writeFile(file, `${JSON.stringify(migrated, null, 2)}\n`, 'utf8');
  return migrated;
}

